#!/usr/bin/env python3
"""
Expands 11 LP21 topics (22 topic instances) from 10 → 50 exercises each.
Injects into the CORRECT files:
  - grades 1-3: science.ts
  - grades 4-6 physics/bio/space/elec: nt.ts
  - grades 4-6 geography/history: rzg.ts
  - grades 1-2 math: math.ts
Also removes orphaned topic blocks from grade4/5/6 science.ts.
"""

import re, os

BASE = os.path.expanduser("~/projects/cleverli/src/data")

# ─── HELPERS ────────────────────────────────────────────────────────────────

def mc(id, diff, q, qEN, qFR, qIT, ans, opts, h1, h2):
    o = '","'.join(opts)
    return f'      {{ id: "{id}", type: "multiple-choice", difficulty: {diff}, question: "{q}", questionEN: "{qEN}", questionFR: "{qFR}", questionIT: "{qIT}", answer: "{ans}", options: ["{o}"], hints: ["{h1}", "{h2}"] }},'

def fib(id, diff, q, qEN, qFR, qIT, ans, h1, h2):
    return f'      {{ id: "{id}", type: "fill-in-blank", difficulty: {diff}, question: "{q}", questionEN: "{qEN}", questionFR: "{qFR}", questionIT: "{qIT}", answer: "{ans}", hints: ["{h1}", "{h2}"] }},'

def drag(id, diff, q, qEN, qFR, qIT, items, zones, answers, h1, h2):
    items_s = ", ".join(f'{{id:"{i}",label:"{l}"}}' for i,l in items)
    zones_s = ", ".join(f'{{id:"{i}",label:"{l}"}}' for i,l in zones)
    ans_s = ", ".join(f'"{k}":"{v}"' for k,v in answers.items())
    return f'      {{ id: "{id}", type: "drag-drop", difficulty: {diff}, question: "{q}", questionEN: "{qEN}", questionFR: "{qFR}", questionIT: "{qIT}", answer: "all", hints: ["{h1}", "{h2}"], dragItems: [{items_s}], dropZones: [{zones_s}], dropAnswers: {{{ans_s}}} }},'

def match(id, diff, q, qEN, qFR, qIT, pairs, h1, h2):
    pairs_s = ", ".join(f'{{id:"{i}",label:"{l}",emoji:"{e}"}}' for i,l,e in pairs)
    return f'      {{ id: "{id}", type: "matching", difficulty: {diff}, question: "{q}", questionEN: "{qEN}", questionFR: "{qFR}", questionIT: "{qIT}", answer: "all", hints: ["{h1}", "{h2}"], pairs: [{pairs_s}] }},'

def mem(id, diff, q, qEN, qFR, qIT, pairs, h1, h2):
    pairs_s = ", ".join(f'{{id:"{i}",label:"{l}",emoji:"{e}"}}' for i,l,e in pairs)
    return f'      {{ id: "{id}", type: "memory", difficulty: {diff}, question: "{q}", questionEN: "{qEN}", questionFR: "{qFR}", questionIT: "{qIT}", answer: "all", hints: ["{h1}", "{h2}"], pairs: [{pairs_s}] }},'

def inject(filepath, topic_id, new_exercises_ts):
    """Find the exercises array closing bracket for topic_id and insert before it."""
    with open(filepath, encoding='utf-8') as f:
        content = f.read()
    
    # Find the topic block start
    pattern = f'id: "{topic_id}"'
    topic_pos = content.find(pattern)
    if topic_pos == -1:
        print(f"  ERROR: topic '{topic_id}' not found in {filepath}")
        return False
    
    # Find 'exercises: [' after the topic position
    exs_pos = content.find('exercises: [', topic_pos)
    if exs_pos == -1:
        print(f"  ERROR: exercises array not found for '{topic_id}'")
        return False
    
    # Count brackets to find the matching '],'
    depth = 0
    i = exs_pos + len('exercises: [')
    while i < len(content):
        c = content[i]
        if c == '[':
            depth += 1
        elif c == ']':
            if depth == 0:
                # This is the closing bracket of exercises array
                # Insert new_exercises_ts before this position
                # Find the newline before this ']'
                insert_pos = i
                new_content = content[:insert_pos] + new_exercises_ts + '\n' + content[insert_pos:]
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(new_content)
                print(f"  ✓ Injected {topic_id} into {os.path.basename(filepath)}")
                return True
            depth -= 1
        i += 1
    print(f"  ERROR: could not find closing bracket for exercises in '{topic_id}'")
    return False

def remove_topic_block(filepath, topic_id):
    """Remove an entire topic block (from { id: "topic_id" to the matching closing },)"""
    with open(filepath, encoding='utf-8') as f:
        content = f.read()
    
    # Find '  {\n    id: "topic_id"'  
    pattern = f'    id: "{topic_id}",'
    pos = content.find(pattern)
    if pos == -1:
        print(f"  SKIP: topic '{topic_id}' not found in {filepath} (may already be removed)")
        return True
    
    # Find the opening '{' of this topic block
    block_start = content.rfind('  {', 0, pos)
    if block_start == -1:
        print(f"  ERROR: cannot find block start for '{topic_id}'")
        return False
    
    # Find closing '},' by counting braces
    depth = 0
    i = block_start
    while i < len(content):
        c = content[i]
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                # This closes the topic block
                # Check for trailing comma
                end = i + 1
                if end < len(content) and content[end] == ',':
                    end += 1
                # Remove including any newline after
                while end < len(content) and content[end] == '\n':
                    end += 1
                    break
                new_content = content[:block_start] + content[end:]
                with open(filepath, 'w', encoding='utf-8') as f:
                    f.write(new_content)
                print(f"  ✓ Removed topic '{topic_id}' from {os.path.basename(filepath)}")
                return True
        i += 1
    print(f"  ERROR: cannot find end of block for '{topic_id}'")
    return False

